    bag_examples_v2_toast: "🎁 Nuovi esempi nella tua borsa: idee regalo, una lista per l'hotel e una per il volo ✨",
    faq_a_bag_examples_list: "Una borsa nuova arriva con esempi che puoi modificare o eliminare come tutto il resto: Casa (spesa, ricette, pasti della settimana), Famiglia (piccoli momenti, una lista per la festa di compleanno, attività e corsi), Idee (idee per il weekend, idee regalo in base a quanto è stretto il legame con la persona e cosa fare con i soldi risparmiati) e Viaggi (posti dove vuoi andare, valigia per il viaggio, valigia per l'hotel e una lista per il volo all'estero). Una borsa che esisteva già riceve una sola volta i più nuovi, nelle sue tasche.",
    faq_q_bag_examples_list: "Quali esempi ci sono in La mia borsa?",
    faq_a_nm_me1_guide: "Me – il tuo personaggio in New Me, nella sua prima forma (Me1). La prima volta, subito dopo l'iscrizione, si apre un portale di luce tra mille scintille e Me ne esce volando, spiega in pochi tocchi cosa ti aspetta e poi resta accanto a ogni domanda: mentre si scelgono i pasti scrive con te nel suo libro, e un tocco sul suo consiglio ne mostra un altro. Alla fine Me festeggia con te e ti porta a fare un breve giro – e quando il giro finisce, ha ancora un piccolo momento con te. Se esci a metà – delle domande o del giro – la volta dopo Me è felice di rivederti e chiede se continuare dallo stesso punto. “Salta” in alto salta l'apertura.",
