    nm_m1_tip_ai: "Un cibo che non è nella lista? Più tardi, in “Cambia”, puoi scriverlo con parole tue – e l'IA fa i calcoli. E ora scegliamo insieme cosa mangiare ogni giorno – e naturalmente puoi sempre cambiare ✨",
