    room_genie_again_no_msg: "Allora è il momento di raggiungere gli obiettivi che hai già fissato. Quando arriverai al prossimo – lì ti aspetterà qualcosa ✨",
    room_genie_again_q: "Di nuovo qui? ✨ Vorresti cambiare qualcos'altro nella tua vita?",
