    room_genie_bye: "A presto",
    room_genie_rest: "Lo spirito del bosco ora riposa – torna domani ✨",
    faq_a_shop_holidays: "Nella Lista della Spesa, tocca il regalo: compaiono in ordine le feste del tuo Paese (quello scelto nelle Impostazioni), con le loro date – calcolate da sole ogni anno. Tocca una festa per avere una lista già pronta di ciò che si compra per l'occasione; è tutto selezionato (tranne quello che è già nella tua lista), togli la spunta a ciò che non ti serve e tocca “Aggiungi alla lista”. Due settimane prima di una festa compare una piccola scheda in cima alla lista; ✕ la nasconde fino alla festa successiva.",
    faq_q_shop_holidays: "Come funziona “Cosa comprare per la festa”?",
    shop_hol_add: "Aggiungi alla lista ({n})",
    shop_hol_added: "Aggiunti alla lista: {n}",
    shop_hol_btn: "Cosa comprare per la festa",
    shop_hol_items_title: "{holiday} – cosa comprare?",
    shop_hol_not_now: "Non ora",
    faq_a_shop_delivery: "Nella Lista della Spesa, tocca il camion: scegli cosa c'è nella consegna (è tutto selezionato), quando arriva – oggi, domani o un altro giorno – e a che ora (mattina, pomeriggio, sera o “Altro…” per un orario tuo). Quegli articoli passano in una scheda “In arrivo” in cima alla lista, con il giorno e l'orario. Quando arriva il giorno, in La Mia Giornata compare “È arrivata la spesa?” (e sulla scheda c'è “È arrivata?”). Se è arrivato tutto, passano in “Da ricomprare”. Se manca qualcosa, tocca ciò che non è arrivato e torna subito in lista.",
    faq_a_shop_departments: "La lista si ordina da sola per reparti del supermercato – frutta e verdura, pane, latticini e uova, carne e pesce, dispensa, surgelati, bevande, snack, pulizia, cura persona, infanzia e animali – così percorri le corsie in ordine. Il reparto si riconosce dal nome dell'articolo. Se un articolo è finito nel posto sbagliato, toccalo e scegli il suo reparto, oppure “Altro…” per scriverne uno tuo.",
    faq_a_shop_share_qty: "Sì. Accanto a ogni articolo, + ne aggiunge uno (×2, ×3…) e − ne toglie uno. Il pulsante di condivisione in cima alla Lista della Spesa invia tutta la lista, ordinata per reparto, su WhatsApp, via email o come copia.",
    faq_a_shop_two_buttons: "Entrambi vogliono dire “comprato”. ✕ è per qualcosa che compri una volta sola: esce dalla lista (e aspetta nell'archivio 🗑️ nel caso fosse un errore). ↺ è per le cose che compri sempre: escono dalla lista e aspettano in “Da ricomprare”; lo apre il piccolo pulsante ↺ accanto al cestino in fondo alla lista, e un tocco lì rimette un articolo in lista. Con “Modifica”, lì dentro, puoi togliere un articolo. Quando aggiungi un articolo, le cose che hai già comprato compaiono come suggerimenti, e se è già in lista diventa semplicemente ×2 invece di una seconda riga.",
    faq_q_shop_delivery: "Come funziona “Ho ordinato la spesa a domicilio”?",
    faq_q_shop_departments: "Perché la mia lista della spesa è divisa in reparti?",
    faq_q_shop_share_qty: "Posso indicare una quantità o mandare la lista a qualcuno?",
