    nm_demo_title: "Come funziona una sostituzione",
    faq_a_new_me_challenge_journal: "Quando una sfida finisce – grande, mini o la sfida della settimana – nel festeggiamento c'è il pulsante 📝 Com'è andata?, che apre una pagina nel diario delle sfide: le sensazioni (cinque faccine), cosa ha aiutato, cosa è stato difficile e cosa mi porto dietro – niente è obbligatorio, e si può fare anche più tardi. Il diario è un diamante nello zaino magico: ogni sfida conclusa con la data e quello che è stato scritto, la più recente per prima – tocca una sfida per leggerla, modificarla o condividerla (si condivide solo ciò che c'è nella pagina). Una sfida conclusa riceve anche una medaglia nelle conquiste, sotto “Sfide che ho completato”. Il diario delle sfide è separato dal diario normale.",
    faq_q_new_me_challenge_journal: "Cos'è il diario delle sfide?",
