    nm_chj_title: "Diario delle sfide",
    nm_chj_write: "Scrivi com'è andata",
    nm_swap_time: "Orario",
    faq_a_ai_reminder_in_text: "Sì: scrivilo insieme all'attività, per esempio «domani alle 17:00 ritirare il pacco, con un promemoria un'ora prima». Il promemoria viene salvato sull'attività stessa: un'ora prima, mezz'ora, il giorno prima e così via, e «ricordamelo» senza un orario significa 10 minuti prima. Un promemoria scritto nel testo ha la precedenza sul campo promemoria della stessa finestra.",
    faq_q_ai_reminder_in_text: "Posso chiedere un promemoria all'assistente IA nella stessa richiesta?",
    myday_meals_all_done: "Tutti i pasti di oggi sono spuntati 🍽️",
    nm_tour_week_text: "Una piccola sfida per la settimana. ✓ ogni giorno – e alla fine una chiave.",
    books_home_chip: "{title} · pag. {page}",
    books_home_of: "di {total}",
    books_home_off_toast: "Il libro ha lasciato la schermata Home",
    books_home_on_toast: "Il libro è nella schermata Home 📖",
    books_home_pin: "Nella schermata Home",
    books_home_q: "A che pagina sono?",
    books_home_save: "Salva",
    faq_a_books_home_chip: "Sì. Nell'Angolo lettura, sulla scheda di un libro che stai leggendo, tocca 📌 Nella schermata Home. Sotto il saluto, nella schermata Home, compare un piccolo pulsante con il libro e la pagina – toccalo, scrivi il nuovo numero di pagina e salva, e i progressi vengono registrati (anche nell'Angolo lettura). Toccando di nuovo 📌 viene tolto. Possono esserci più libri insieme – un pulsante per ciascuno – ed è uguale su ogni dispositivo.",
    faq_a_new_me_week_challenge: "Una piccola sfida di una settimana, scelta da te. Nel corridoio c'è una grande scheda: “Su cosa vuoi lavorare questa settimana?” – toccala, scegli un'area (con me, con gli altri, imparare e crescere, calma, piccoli passi coraggiosi, casa e routine) e una sfida, e decidi quando parte. Le stesse sfide si trovano anche nella schermata delle sfide, sotto 🌱 Crescita personale. Ogni giorno metti un ✓ sulla scheda (un giorno libero a settimana), e ogni settimana conclusa porta una nuova chiave per il mondo segreto. “Leggere 2 pagine al giorno” si spunta da sola con le pagine registrate nell'Angolo lettura. Quando la settimana finisce, 📌 Tienila come attività quotidiana la aggiunge a La Mia Routine all'ora che scegli, con un ✓ ogni giorno. Una sola sfida della settimana alla volta; le grandi sfide e le mini sfide continuano in parallelo.",
    faq_a_room_genie: "Sul portico sul mare, un tocco alla lampada di Aladino fa uscire lo spirito del bosco – e comincia una conversazione: qual è il tuo desiderio (cosa vorresti cambiare nella tua vita), come ci si sentirà quando si avvera, cosa è difficile lungo la strada e come si può trasformare la situazione di adesso in qualcosa di buono. Poi più o meno quanto tempo ci vorrà, un primo piccolo passo e altri due, e un “se… allora…” per quando diventa difficile. Alla fine compare tutto il desiderio passo dopo passo, e può diventare un obiettivo in I Miei Obiettivi (i passi diventano traguardi del sentiero, con una data in base al tempo scelto; lì si può cambiare tutto) oppure essere salvato nel diario – e poi lo spirito saluta. Non viene salvato nulla se non si sceglie una delle due. Dalla seconda visita in poi, lo spirito chiede prima se vorresti cambiare qualcos'altro nella tua vita: sì – la stessa conversazione; non ora – un promemoria per raggiungere gli obiettivi già fissati. Lo spirito esce una volta al giorno: dopo che un desiderio è stato salvato (o dopo “Non ora”), riposa fino a domani. Le domande seguono un metodo molto noto per trasformare un desiderio in un piano: desiderio, risultato, ostacolo e piano.",
    faq_q_books_home_chip: "Posso vedere il mio libro e la pagina nella schermata Home?",
    faq_q_new_me_week_challenge: "Cos'è la sfida della settimana?",
    faq_q_room_genie: "Cosa fa il genio della lampada?",
