    faq_a_new_me_game: "In New Me i pulsanti del gioco restano sempre nello stesso posto – nel corridoio, nella stanza segreta e ovunque nel bosco; cambia solo il dipinto al centro. In alto: il giorno del percorso, le chiavi, la serie e l'energia di oggi (quanto è stato mangiato rispetto al piano), e sotto la prossima missione – il prossimo pasto alla sua ora (un tocco lo apre, con ✓ Mangiato). Di lato: tutta la giornata, sfide e il mio percorso, e accanto la sfida della settimana – i suoi 7 giorni e una ✓ per oggi. In basso: lo zaino magico (tutto New Me – mappa del mondo, il mio percorso, lista della spesa, conquiste, diario delle sfide, misure, foto dei progressi, calendario mensile, tabella giornaliera, promemoria, PDF del menu e impostazioni; si apre come una schermata a sé). La mappa del mondo, la prima cosa nello zaino, mostra ogni posto del bosco – tocca un posto per andarci; un posto chiuso mostra quante chiavi servono. Me è il tuo personaggio sul sentiero nel bosco: comincia come Me1, dopo qualche sfida (4 chiavi) cresce e diventa Me2, e verso la fine (9 chiavi) Me3 – con una trasformazione da guardare. Tocca Me per vedere tutte le fasi – ogni personaggio già raggiunto si può scegliere di nuovo, così uno precedente può tornare. Me fluttua: lo trascini con il dito o con il mouse, e l'ingresso che tocca si apre (su uno bloccato si vede quante chiavi mancano). Me ti segue anche in ogni stanza e in ogni posto, e fluttua dove lo lasci: trascinalo ovunque, e trascina l'anello luminoso sotto di lui per farlo girare completamente su se stesso; guarda nella direzione in cui si muove (sul computer: le frecce lo muovono, Q ed E lo girano). Nel corridoio, la piccola 🏠 sotto la barra superiore torna alla schermata Home; in ogni stanza e in ogni posto, il pulsante nello stesso angolo torna al corridoio.",
    faq_q_new_me_game: "Come funzionano i pulsanti del gioco, la mappa del mondo e Me?",
