    faq_a_new_me_menu_build: "Prima il questionario chiede quali pasti fai e quando (2 pasti + uno spuntino, 2 pasti + una cena leggera, o entrambi) e se la sera c'è qualcosa – da mangiare o da bere, cosa e a che ora. Con “2 pasti + uno spuntino” i pasti sono pranzo (11:30) e cena (19:00), con lo spuntino alle 16:00. Poi compaiono tutte le proposte per quei pasti. Scegli fino a 2 preferiti per ogni pasto – il menu mostra “questa o quella”. In alcune proposte (pita e crema, corn flakes e latte, qualcosa di leggero) scegli fino a 3 cose che ti piacciono, ognuna nella sua porzione, e il menu mostra “questa o quella o quell'altra”; le calorie si adeguano a quello che hai scelto. Caffè e bevande funzionano allo stesso modo. Ogni scelta viene bilanciata, così la giornata arriva esattamente a 1.300 o 1.500. Per cambiare in qualsiasi momento: ⚙️ Impostazioni → 🍽️ Crea il tuo menu, oppure “Scegli fino a 3 che ti piacciono” sulla scheda del pasto.",
    faq_q_new_me_menu_build: "Come si costruisce il menu di New Me?",
