    faq_a_myday_water_toggle: "Sì. Il bicchiere d'acqua in “La Mia Giornata” (con + per un bicchiere in più) è visibile di default. Per nasconderlo, disattiva “Mostra l'acqua in ‘La Mia Giornata’” in Impostazioni > Personalizzazione e calendario. Non si cancella niente: Monitoraggio Acqua continua a funzionare e, riattivandolo, il bicchiere torna.",
    faq_q_myday_water_toggle: "Posso nascondere l'acqua in “La Mia Giornata”?",
    myday_water_toggle_label: "Mostra l'acqua in “La Mia Giornata”",
    faq_a_routine_newme_sync: "Con New Me, l'⚙️ di La Mia Routine ha un interruttore “Sincronizza con New Me”. Acceso (predefinito), i pasti di oggi di New Me compaiono in La Mia Giornata e in La Mia Routine – al posto dei pasti della routine che sono stati nascosti. Spento, i pasti di New Me escono da entrambe e la routine torna esattamente com'era. Non si cancella nulla: riaccenderlo riporta tutto e chiede quali pasti della routine nascondere.",
    faq_q_routine_newme_sync: "Come attivo o disattivo la sincronizzazione di New Me con La Mia Routine e La Mia Giornata?",
