    theme_name_watercolor_wash: "Acquerello",
    faq_a_food_list_languages: "L'elenco di alimenti integrato è nato con piatti israeliani e i loro nomi in ebraico. In tutte le altre lingue ogni alimento compare con il suo nome inglese, e la ricerca trova qualsiasi nome inglese che conosce (per esempio 'broth' trova Clear soup); gli alimenti che hanno solo un nome in ebraico non compaiono. Ciò che non è nell'elenco si può semplicemente scrivere con parole tue: la stima con l'IA funziona in tutte le lingue.",
    faq_q_food_list_languages: "Perché l'elenco degli alimenti mostra nomi in inglese, e meno alimenti, nella mia lingua?",
    settings_copyright_line: "© 2026 tutti i diritti riservati. app sviluppata da eden zabari.",
    workout_ready_replace_btn: "Sostituisci",
    faq_a_sport_workout_ai: "In I miei allenamenti → ⋯ → Piano con IA (e, con la tabella vuota, anche nel riquadro accanto ai piani pronti). Rispondi con pochi tocchi – quante volte a settimana, quando, luogo, livello e obiettivo, quasi tutti anche con \"Altro\" – e, se vuoi, aggiungi una riga libera, come un ginocchio sensibile o correre 5 km entro l'estate. L'IA crea una settimana intera: tipi di allenamento, giorni, orari, durata, intensità, esercizi e giorni di riposo. Prima di salvare c'è un'anteprima: \"Mettilo nella mia tabella\" (al posto della tabella o in aggiunta), \"Un'altra proposta\" (fino a 3 volte) o \"Cambia risposte\". Il piano è moderato di proposito, e se citi un dolore o un infortunio ricevi opzioni delicate e il consiglio di sentire un professionista. Usa la stessa quota IA dell'agenda e della routine: 5 volte gratis e 60 al mese con Premium.",
    faq_q_sport_workout_ai: "Come creo un piano di allenamento con l'IA?",
