    workout_ai_other: "Altro",
    workout_ai_replace: "Al posto della mia tabella",
    workout_ai_title: "Piano di allenamento con IA",
    workout_ai_when_evening: "Sera",
    workout_ai_when_label: "Quando",
    workout_ai_when_morning: "Mattina",
    workout_ai_when_noon: "Mezzogiorno",
    workout_ai_when_ph: "es. dopo il lavoro, o 17:30",
    workout_ai_working: "Creazione del piano…",
    faq_a_sport_workout_jar: "Ogni tipo di allenamento ha la sua stella colorata: corsa rosa, camminata verde, nuoto blu e così via. Ogni allenamento registrato questa settimana, dalla tabella o a parte, fa cadere la sua stella nel barattolo in cima a I miei allenamenti, e il barattolo si riempie fino al tuo obiettivo settimanale (toccalo per cambiare l'obiettivo). Raggiunto l'obiettivo, il barattolo brilla. Il barattolino accanto conta quante settimane di fila l'hai riempito.",
    faq_q_sport_workout_jar: "Cosa sono le stelle colorate e il barattolo in I miei allenamenti?",
    faq_a_sport_workout_gcal: "Sì: in ⋯ → Google Calendar (dopo aver collegato Google Calendar nelle Impostazioni). Ogni allenamento con un orario diventa un evento che si ripete ogni settimana nei suoi giorni, e le modifiche nell'app lo aggiornano. I promemoria arrivano solo dall'app, quindi Google non ne aggiunge di suoi, e gli allenamenti non compaiono mai due volte nell'app. Toccandolo di nuovo si tolgono da Google Calendar solo gli allenamenti.",
    faq_q_sport_workout_gcal: "I miei allenamenti possono comparire in Google Calendar?",
    workout_gcal_btn: "Google Calendar",
    workout_gcal_error: "Non è stato possibile aggiornare Google Calendar: riproverà alla prossima modifica",
    workout_gcal_not_connected: "Prima collega Google Calendar nelle Impostazioni",
    workout_gcal_off_toast: "Gli allenamenti sono stati tolti da Google Calendar",
    workout_gcal_on_toast: "I tuoi allenamenti sono in Google Calendar",
    faq_a_sport_workout_reminder: "Sì: in un allenamento, Promemoria: 10 minuti, 30 minuti o un'ora prima, oppure un tempo personalizzato (l'allenamento deve avere un'ora). Suona come gli altri promemoria, una volta e in un solo posto: nell'app se è aperta, altrimenti sul telefono. \"Fatto\" registra l'allenamento nello storico, e \"Non ancora\" lo ricorda di nuovo tra 5 minuti.",
    faq_q_sport_workout_reminder: "Posso ricevere un promemoria prima di un allenamento?",
    workout_reminder_30min: "30 minuti prima",
    workout_reminder_label: "Promemoria",
    workout_reminder_need_time: "Aggiungi un'ora per ricevere un promemoria",
    faq_a_sport_workout_share: "In ⋯ → Condividi la settimana diventa un'immagine effetto vetro nei colori del tuo tema, con un link discreto all'app (sul telefono va subito al menu di condivisione, sul computer l'immagine viene salvata). ⋯ → PDF da stampare apre una pagina pulita con tutta la settimana e una casella da spuntare accanto a ogni allenamento ed esercizio: scegli \"Salva come PDF\" o stampala. Il piano compare anche nel report dei dati nelle Impostazioni, nella parte Sport.",
    faq_q_sport_workout_share: "Come condivido o stampo la mia settimana di allenamento?",
    share_image_saved: "L'immagine è salvata: puoi allegarla",
    share_save_image: "Salva l'immagine",
    workout_pdf_btn: "PDF da stampare",
    workout_share_btn: "Condividi",
    faq_a_sport_workout_board: "In ⋯ → Tabellone settimanale ogni giorno è una colonna: trascina un allenamento su un altro giorno (sul telefono, prima tieni premuto). In un allenamento, \"Anche in La Mia Routine\" lo mette nella tua routine alla sua ora e nei suoi giorni, e le modifiche restano sincronizzate nei due sensi; da un elemento di La Mia Routine, \"Aggiungi ai miei allenamenti\" fa il contrario. Una ✓ da una parte conta in entrambe, e in La Mia Giornata compare una volta sola: nel chip accanto all'acqua.",
    faq_q_sport_workout_board: "Come sposto un allenamento a un altro giorno e lo collego a La Mia Routine?",
    routine_in_workouts_btn: "Apri nei miei allenamenti",
    routine_to_workout_btn: "Aggiungi ai miei allenamenti",
    routine_to_workout_done: "Aggiunto ai miei allenamenti 💪",
    workout_delete_confirm_routine: "Verrà tolto dal piano e da La Mia Routine. Gli allenamenti già registrati nello storico restano.",
    workout_moved: "Spostato a {day}",
    workout_routine_need_time: "Aggiungi un'ora per metterlo in La Mia Routine",
    workout_routine_toggle: "Anche in La Mia Routine",
    workout_view_board: "Tabellone settimanale",
    workout_view_timeline: "Cronologia",
    faq_a_sport_workout_plan: "In Monitoraggio Allenamenti, sotto \"I miei allenamenti\": + Allenamento – tipo, giorni, ora, durata, intensità e luogo (anche \"Altro\"). Gli allenamenti di forza, funzionali e di nuoto possono avere un elenco di esercizi, e Riposo segna un giorno di riposo. Puoi anche partire da un piano pronto. L'allenamento di oggi appare in grande, con tutta la settimana sotto; ✓ lo registra nello storico allenamenti insieme alla sua intensità. In ⋯ imposti un obiettivo settimanale (allenamenti o minuti): ogni allenamento fatto fa cadere la sua stella nel barattolo.",
    faq_a_sport_workout_today: "In La Mia Giornata, accanto all'acqua, un piccolo chip mostra l'allenamento di oggi: toccandolo si aprono i dettagli, ✓ e ▶. ▶ avvia un timer che continua a scorrere nel chip della schermata iniziale, e \"Termina\" registra l'allenamento con il tempo reale. Se in New Me è attiva la sfida \"Due settimane in movimento\", un allenamento registrato conta da solo.",
    faq_q_sport_workout_plan: "Come pianifico la mia settimana di allenamento?",
    faq_q_sport_workout_today: "Dove vedo l'allenamento di oggi, e come funziona il timer?",
