    faq_a_new_me_magic_themes: "Cinque temi scintillanti inclusi in New Me: Bosco incantato, Polvere di stelle, Fata delle rose, Aurora magica e Tramonto dorato. Scegline uno dentro New Me (⚙️ Impostazioni > Colori) o in Impostazioni > Aspetto e schermo, e un pennello di brillantini dipinge lo schermo con quel tema. Un tema magico aggiunge brillantini in tutta l'app e a ogni tocco. Puoi tornare a qualsiasi altro tema quando vuoi.",
