    apptour_focus_text: "Tutto si fa da parte tranne l'unica cosa di adesso, con una grande ✓. Poi compare la successiva.",
    apptour_m_presets_text: "I tuoi pasti salvati in un unico posto: ricerca, usati di recente, per momento della giornata – e ＋ ne aggiunge uno a oggi.",
    apptour_night_text: "🌙 scurisce tutta l'app; ☀️ riporta il giorno.",
    apptour_noteline_text: "Scrivi e tocca ➤: viene salvato nelle tue note. 📝 all'inizio passa a 🛒 la spesa o a 🍎 un pasto salvato.",
    apptour_search_text: "Note, spesa, calendario, ricette, quaderni, obiettivi, tabelle e libri: una sola ricerca trova tutto.",
    faq_a_new_me_ai_menu: "Prima del menu, il questionario chiede quali pasti fai e quando (2 pasti + uno spuntino, 2 pasti + una cena leggera, o entrambi), se la sera mangi qualcosa di piccolo e a che ora, cosa non mangi e come bevi il caffè o il tè. Poi l'IA crea 3 proposte per ogni pasto – ciascuna della misura della sua parte di giornata, così la giornata arriva sempre esattamente a 1.300 o 1.500 – e idee per le bevande, salvate come le tue bevande abituali. Scegli fino a 2 preferiti per pasto; le proposte del menu originale sono subito sotto, e in 🔄 Cambia arrivano dopo il tuo menu personale. 🔄 Altre proposte crea un nuovo giro (3 volte per questionario). Per cambiare le risposte o creare un nuovo menu quando vuoi: ⚙️ Impostazioni → ✨ Menù personale (IA).",
    faq_q_new_me_ai_menu: "Come funziona il menu personale di New Me?",
    nm_ai_menu_building: "Sto preparando un menu per i tuoi pasti e orari…",
    nm_ai_menu_drinks: "Bevande per te",
    nm_ai_menu_error: "Il menu personale non si è potuto creare adesso – ecco il menu originale. Puoi riprovare, o più tardi da ⚙️ Impostazioni.",
    nm_ai_menu_original: "Dal menu originale",
