    apptour_s_gcal_inside_text: "Collega Google Calendar una volta sola: eventi e attività restano sincronizzati in entrambe le direzioni.",
    apptour_s_menu_text: "Qui c'è tutto quello che puoi regolare, in cinque gruppi. Apriamoli 👇",
    apptour_skip_part: "Salta questa parte",
    apptour_start: "Inizia il tour",
    nm_sales_premium: "Include tutto Premium",
    nm_unlock_premium: "E anche tutto Premium è sbloccato.",
    settings_sub_status_newme: "Premium è incluso nel tuo New Me.",
    room_back_to_shelf: "Alla mensola",
    faq_a_new_me_day_total: "Ogni giornata corrisponde esattamente al piano: i pasti, circa 150 calorie per caffè e bevande durante il giorno, e quello che è stato scelto per la sera – qualcosa di piccolo da mangiare o qualcosa da bere. Per la sera scegli fino a 3 che ti piacciono (per esempio una banana, uno yogurt o 2 quadratini di cioccolato fondente; oppure una tisana, tè con un po' di latte o latte caldo), e le loro calorie vengono tolte dai pasti. Ogni scelta si bilancia da sola: un'opzione più piccola o più grande, un pasto tolto, la colazione piccola e il piccolo pasto che arriva con lei, o la sera – la differenza viene aggiunta ai pasti o tolta, a ciascuno secondo la sua grandezza, e sotto ogni pasto c'è scritto quanto (+ o −) e cosa aggiungere o togliere. Un pasto già spuntato resta come è stato registrato. Nel questionario ogni pasto mostra il suo aggiustamento, e un piccolo riquadro mostra pasti, bevande, la sera e il totale. Voglia di qualcos'altro quel giorno? Mantieni il totale sulle stesse calorie o meno.",
    faq_q_new_me_day_total: "Come fa una giornata New Me a fare esattamente 1.300 / 1.500, e dove contano le bevande?",
