    nm_less_line: "{n} calorie in questo pasto, perché la giornata faccia {plan} – per esempio {ideas}",
    nm_less_line_late: "{n} calorie in questo pasto, per qualcosa di piccolo alle {time} – per esempio {ideas}",
    nm_swap_balanced: "{n} calorie distribuite tra i pasti, perché la giornata faccia {plan}",
    books_quotes_chip: "Citazioni",
    faq_a_book_quotes: "Sulla mensola della stanza segreta (Citazioni), o con la piccola etichetta 💬 Citazioni nell'Angolo lettura – è la stessa lista. Tocca \"+ Citazione\", scrivi la frase e scegli il libro dal tuo Angolo lettura, oppure digita un altro titolo con \"✏️ Altro\"; l'autore è facoltativo. ✏️ modifica una citazione e 🗑️ la elimina. Le citazioni sono segnalibri da scorrere: 🎨 in alto passa a foto o a una bacheca di schede.",
    faq_a_room_wish_jar: "Sulla mensola della stanza segreta c'è un barattolo di vetro per i sogni. Tocca il barattolino sul ripiano più alto (o Mensola > Il barattolo dei desideri) e scrivi come vorresti che fosse la tua vita – in grande quanto vuoi, senza giusto o sbagliato. Ogni desiderio diventa un bigliettino piegato e cade nel barattolo. “Pesca un bigliettino” ne apre uno a caso, e ogni bigliettino si può aprire anche da solo. Dalla seconda volta che apri lo stesso desiderio, puoi trasformarlo in un obiettivo e dividerlo in piccoli passi. Una volta a settimana compare con delicatezza un bigliettino con uno dei tuoi desideri – senza pressione, solo un promemoria di dove stai andando.",
    faq_q_book_quotes: "Dove tengo le citazioni dei libri che ho amato?",
    faq_q_room_wish_jar: "Cos'è il barattolo dei desideri nella stanza segreta?",
