    room_wish_to_goal: "🎯 Trasformalo in un obiettivo, a piccoli passi",
    room_wish_written: "Scritto il {date}",
    faq_a_saved_meals_page: "I pasti salvati hanno una pagina tutta loro: Nutrizione e Metriche > ⭐ Pasti salvati (o ⭐ nel menu). La ricerca in alto trova un pasto per nome o ingrediente, \"Usati di recente\" mostra quello che hai aggiunto ultimamente, e le schede (Colazione, Pranzo, Cena, Zuppe…) mostrano ogni momento della giornata. \"+ Oggi\" aggiunge un pasto al Diario Alimentare Giornaliero di oggi, nel prossimo spazio libero. Tocca un pasto per modificarlo o eliminarlo, e ＋ in alto ne aggiunge uno nuovo.",
