    presets_tab_soup: "Zuppe",
    presets_tab_sweet: "Dolcetti",
    faq_a_notes_sticky_look: "Le note sono una breve lista di schede di vetro: 🎨 in alto nelle Note cambia l'aspetto di tutte le Note – la lista, i pulsanti dei giorni in alto e la finestra in cui si scrive una nota (vetro, lista pulita, schede o nastro washi). Una nota trascinata mantiene esattamente il suo aspetto e il suo colore. Tocca il testo di una nota per aprirla: lì puoi modificarla, cambiarne i colori e vedere quando è stata scritta l'ultima volta. Tocca ○ quando è fatta, e × la sposta nell'archivio (🗑️ in fondo alla lista la recupera). Trascinala da ⠿ per cambiare l'ordine, sotto “Più tardi” o su un giorno in alto. ! segna una nota come urgente – sale dolcemente nelle prime righe con una piccola etichetta “Urgente”; un altro tocco la toglie.",
    faq_q_notes_sticky_look: "Come apro, modifico o tolgo una nota?",
    note_to_archive_btn: "Sposta nell'archivio",
    faq_a_routine_clash: "Se a quell'orario negli stessi giorni c'è già qualcosa, compaiono due scelte: \"Sostituisci\" – il nuovo elemento prende quell'orario e scegli un altro orario per quello che c'era (quando modifichi un elemento esistente viene proposto il suo orario precedente, così i due si scambiano semplicemente), oppure \"Tutti e due\" – restano entrambi allo stesso orario, uno sotto l'altro. Se i giorni sono diversi (per esempio uno da domenica a giovedì e l'altro il venerdì), non viene chiesto nulla.",
    faq_q_routine_clash: "Cosa succede se metto un elemento della routine a un orario già occupato?",
    routine_clash_both: "✌️ Tutti e due – entrambi alle {time}",
    routine_clash_move_btn: "Sposta e salva",
    routine_clash_move_to: "A che ora spostare \"{title}\"?",
    routine_clash_replace: "🔄 Sostituisci – e sposta \"{title}\" a un altro orario",
    routine_clash_title: "Alle {time} c'è già: {title}",
    faq_a_new_me_coffee: "Sotto il menu di oggi c'è un breve riepilogo: quante calorie fanno tutti i pasti della giornata, quanto resta per caffè e bevande, e i pulsanti del caffè e delle bevande scelti – basta un tocco per aggiungerli alle Bevande. In “Scegli fino a 3 che ti piacciono” sotto i pulsanti (e nel questionario) scegli cosa compare: acqua / acqua frizzante, tisana, una bibita diet, nero / americano (~5), tè con un po' di latte (~25), caffè allungato con acqua e fino a 100 ml di latte o bevanda vegetale (~50), cioccolata calda leggera, latte caldo o caffè normale / latte macchiato (~120).",
    faq_q_new_me_coffee: "Dove aggiungo il caffè, e come so quanto mi resta per la giornata?",
