    nm_late_ideas_none: "Oggi resta pochissimo – tè, acqua o caffè nero",
    nm_late_room_line: "Qualcosa di piccolo prima di dormire · restano ~{n} kcal oggi",
    faq_a_recipe_examples: "Sotto le tue ricette ci sono ricette di esempio: colazioni, insalate, zuppe, piatti principali, contorni, spuntini, dolci e piatti vegani, ognuna con il tempo di preparazione, le calorie per porzione e quanti grammi pesa una porzione. Tocca una ricetta per aprirla, e \"Salva nelle Mie Ricette\" crea una tua copia che puoi modificare. Le etichette delle categorie filtrano, e toccare di nuovo la stessa etichetta mostra tutto.",
    faq_a_recipe_grams: "Dentro una ricetta, accanto alle calorie, c'è scritto \"1 porzione ≈ X g\". Nelle tue ricette, compila \"Grammi per porzione\" (e, se vuoi, il tempo di preparazione) nel modulo della ricetta: sono entrambi facoltativi, e il tempo compare sulla fascia colorata della ricetta.",
    faq_q_recipe_examples: "Cosa sono le ricette di esempio in Le Mie Ricette?",
