    recipe_minutes_placeholder: "Tempo di preparazione (minuti)",
    recipe_save_example_btn: "Salva nelle Mie Ricette",
    recipe_saved_example: "✓ Salvata nelle Mie Ricette",
    recipe_saved_example_toast: "Salvata nelle Mie Ricette: lì puoi modificarla",
    recipes_examples_title: "Ricette di esempio",
    faq_a_recipe_scan_multi: "Sì. In \"Aggiungi Ricetta\" tocca 📷 e scegli una foto o più (fino a 6; va bene anche un PDF). Ognuna compare in un breve elenco dove scegli cosa contiene: Tutto, Ingredienti o Preparazione, e \"➕ Un'altra foto\" ne aggiunge altre. Poi tocca \"✨ Scansiona la ricetta\": l'IA unisce tutto in un'unica ricetta, in ordine e senza righe ripetute, e conta come una sola scansione. Anche più foto scelte da 📷 Foto nell'assistente IA si aprono qui.",
    faq_q_recipe_scan_multi: "Posso scansionare una ricetta da più foto, per esempio gli ingredienti e i passaggi separati, o due pagine?",
    recipe_scan_add_more: "➕ Un'altra foto",
    recipe_scan_part_all: "Tutto",
    recipe_scan_part_ingredients: "Ingredienti",
    recipe_scan_part_steps: "Preparazione",
    recipe_scan_remove_photo: "Togli la foto",
    recipe_scan_run_btn: "✨ Scansiona la ricetta",
    recipe_scan_too_many: "Fino a {n} foto per ricetta",
    faq_a_note_written_at: "Tocca il testo della nota per aprirla. Dentro, sotto il testo, compare quando è stata scritta l'ultima volta, con data e ora esatte. Solo una modifica al testo lo aggiorna: archiviarla e ripristinarla, spuntarla ✓, i colori o spostarla non lo cambiano.",
    faq_q_note_written_at: "Come vedo quando ho scritto una nota?",
    note_written_at: "Scritta l'ultima volta: {date}",
    faq_a_new_me_month: "Nello zaino magico → Calendario mensile: ogni giorno è colorato in base a quanti pasti sono stati spuntati, le frecce ‹ › passano da un mese all'altro, e sotto il calendario c'è la media giornaliera delle calorie del mese. Toccando un giorno si vede quanti pasti sono stati spuntati e quante calorie sono state mangiate quel giorno.",
    faq_q_new_me_month: "Dove rivedo il mese passato e la media delle calorie in New Me?",
    nm_month_avg: "Media del mese: {kcal} calorie al giorno · giorni registrati: {n}",
    nm_month_day_empty: "In questo giorno non è stato registrato nulla.",
    nm_month_day_line: "Pasti spuntati: {checks} · calorie: {kcal}",
    nm_extra_line_small: "{n} calorie per questo pasto, dalla colazione piccola – per esempio {ideas}",
    faq_a_new_me_small_breakfast: "Una colazione leggera (circa 170 kcal): una pita di farro (fino a 100 kcal) con una crema spalmabile o un formaggio, e una verdura – scegli fino a 3 che ti piacciono, per esempio 1 cucchiaino di crema al cioccolato, 1 cucchiaino di burro di arachidi o una fetta di formaggio a pasta dura (fino al 22%). Visto che è piccola, con lei arriva “In più un piccolo pasto” a un altro orario (un'ora e mezza dopo, per esempio 11:30 → 13:00 – si può scegliere anche un altro orario): un'altra pita e crema, yogurt proteico e frutta, gallette di riso e formaggio, cereali e latte o mezza pita e uova – fino a circa 200 kcal, con il suo ✓. Quello che resta ancora viene diviso tra gli altri pasti, e ogni pasto mostra quanto gli è stato aggiunto, così il totale del giorno resta come nel piano. Puoi sceglierla nel questionario o passarci solo per oggi con 🔄 – per esempio quando fai colazione tardi.",
    faq_q_new_me_small_breakfast: "Cos'è la “colazione piccola” nel menu di New Me?",
