    weather_sky_storm: "Temporale",
    faq_a_ai_icon: "Sì – in Impostazioni > Aspetto e schermo. La bolla morbida è quella predefinita, e con Premium puoi scegliere anche un cervello fluttuante o un robot.",
    faq_a_new_me_favorites: "Sì. Nel questionario (e quando lo rifai dalle impostazioni) puoi scegliere fino a 2 opzioni per ogni pasto. La prima appare nel menu, con una riga “o” sotto per la seconda: toccandola passi a quella solo per oggi. E se la colazione non è stata mangiata in tempo, “⏰ Più tardi” la sposta più avanti nella giornata, senza cambiare le calorie.",
    faq_a_theme_mode: "Alcuni temi speciali sono più belli in scuro – Acquerello, Aurora boreale, Barbie e i due temi glitter –, quindi sceglierne uno porta l'app in modalità scura, mentre scegliere qualsiasi altro tema (anche il razzo) la porta in chiara. Nero e Grigio scuro restano scuri. Puoi sempre cambiare dopo con 🌙 nel menu o con Modalità Chiara nelle impostazioni.",
    faq_a_water_month: "Nel monitoraggio dell'acqua. Ogni voce del registro di oggi mostra l'ora in cui è stata aggiunta, e \"Tabella mensile\" apre tutto il mese: ogni giorno mostra quanti litri sono stati bevuti (✓ quando l'obiettivo giornaliero è stato raggiunto), e toccando un giorno compaiono le sue voci con gli orari.",
    faq_q_ai_icon: "Posso cambiare l'icona dell'assistente AI?",
    faq_q_new_me_favorites: "Posso scegliere due opzioni preferite per un pasto in New Me?",
