    dev_sim_panel_title: "PM – solo per te",
    faq_a_new_me_weight_optional: "No. Sia il peso attuale sia il peso obiettivo del questionario sono facoltativi. Se più avanti si aggiunge una pesata (⚖️ Peso in “Il mio percorso” di New Me, o nel monitoraggio del peso), i progressi si contano dalla prima.",
    faq_q_new_me_weight_optional: "Devo inserire il mio peso in New Me?",
    nm_unlock_desc: "Il menu, le sfide e il percorso sono pronti – passo dopo passo, insieme.",
    nm_unlock_title: "New Me sbloccato!",
    room_reveal_star: "Una nuova stella si è accesa nel telescopio sul tetto ✨",
    faq_a_room_records: "Il giradischi è nella stanza fin dall'inizio, sul ceppo accanto alla poltrona. I suoi dischi aprono su YouTube i videoclip ufficiali dei grandi successi degli ultimi anni, e sotto ci sono cinque melodie calme che suonano proprio qui nella stanza: il disco gira mentre suonano, e “⏹ Ferma” spegne la musica.",
    faq_a_room_roof_gifts: "Arrivano con l'8ª chiave. Toccando il telescopio si può guardare attraverso di esso: il cielo notturno da vicino (trascina, o usa le frecce, per guardarti intorno), e le tue sfide concluse vi formano una costellazione, una stella per ogni sfida; toccando una stella si vede quale era. Toccando il piccolo forziere si apre (per ora è vuoto) e un altro tocco lo richiude.",
    faq_q_room_records: "Cosa c'è sul giradischi della stanza segreta?",
    faq_q_room_roof_gifts: "Cosa sono il telescopio e il forziere sul tetto?",
    room_chest_letter: "Una letterina per te",
    room_chest_letter_1: "Ogni piccolo passo del cammino è stato vero – e ognuno conta.",
    room_chest_letter_2: "Trattarsi con gentilezza fa parte del cammino, non è una pausa.",
    room_chest_letter_3: "Ci sono giorni più leggeri e giorni più pesanti. Esserci in entrambi è la vera forza.",
    room_chest_letter_4: "Riposare è permesso. Anche il riposo è un passo avanti.",
    room_chest_letter_5: "I cambiamenti che durano sono quelli silenziosi: si costruiscono giorno dopo giorno.",
    room_chest_letter_6: "Oggi è una buona giornata per sentire orgoglio, anche solo un po'.",
    room_chest_letter_7: "Non serve fare tutto. Solo la prossima piccola cosa.",
    room_chest_letter_8: "Qualunque cosa sia successa ieri, oggi è un nuovo inizio.",
    room_chest_locked: "3 giorni di fila con ✓ aprono il forziere · {n}/3",
    room_chest_next: "Il forziere si richiude: altri 3 giorni di fila lo apriranno.",
