    room_vinyl_here: "🎻 Melodie calme, qui nella stanza",
    room_vinyl_yt: "🎬 I videoclip ufficiali su YouTube",
    dev_sim_buy: "Come se fosse acquistato – vedere come si apre tutto",
    dev_sim_lock: "Blocca – vedere com'è prima dell'acquisto",
    dev_sim_locked_toast: "🔒 Bloccato – ecco com'è prima dell'acquisto",
    faq_a_new_me_preview: "Sì. La pagina di New Me si apre con un breve video di quello che succede dentro: il questionario, le lampade del corridoio, lo zaino, le sfide e le chiavi. Sotto c'è tutto ciò che è incluso, uno sguardo a una giornata e risposte brevi.",
    faq_q_new_me_preview: "Si può vedere New Me prima di comprarlo?",
    nm_trailer_c1: "Un breve questionario – e il tuo menu è pronto",
    nm_trailer_c2: "Ogni pasto è una lampada nel tuo corridoio",
    nm_trailer_c3: "Nello zaino: il menu di oggi, l'acqua e la spesa",
    nm_trailer_c4: "Una piccola sfida completata – una chiave in più",
    nm_trailer_c5: "E dietro ogni porta – qualcosa solo per te",
    nm_trailer_end: "Si comincia oggi, passo dopo passo",
    nm_trailer_label: "🎬 Un breve video: cosa succede in New Me",
    nm_trailer_pause: "Metti in pausa il video",
    nm_trailer_play: "Riproduci il video",
    nm_trailer_replay: "Guarda di nuovo",
    ai_chat_food_edit: "✏️ Correggi calorie / proteine",
    ai_chat_food_invalid: "Le calorie devono essere un numero maggiore di 0",
    ai_chat_food_updated: "Aggiornato:",
    faq_a_ai_chat_food_fix: "Sì. Sotto la risposta nella chat tocca ✏️ Correggi calorie / proteine, cambia i numeri e tocca Salva. Cambia solo ciò che è appena stato aggiunto – anche se si è unito a uno spuntino già presente. L'IA può sbagliare, quindi conviene dare un'occhiata.",
    faq_a_new_me_home_btn: "Con New Me, un piccolo 💎 accanto alla modalità focus, in alto nella schermata Home, apre il menu di oggi. I pasti di oggi compaiono anche in La Mia Giornata, ognuno con la sua ✓.",
    faq_a_routine_item_days: "Sì. Tocca l'elemento in La Mia Routine e scegli i suoi giorni in 📅 Giorni – per esempio solo dal lunedì al venerdì. Negli altri giorni non compare in La Mia Giornata e non ha la ✓; in La Mia Routine resta, più sbiadito, con i suoi giorni accanto. La scheda che chiede di un elemento dopo 3 giorni senza ✓ conta solo i giorni di quell'elemento.",
    faq_q_ai_chat_food_fix: "Si possono correggere calorie o proteine dopo che l'assistente ha registrato un cibo?",
    faq_q_new_me_home_btn: "Dov'è New Me nella schermata Home?",
    faq_q_routine_item_days: "Un elemento de La Mia Routine può valere solo in certi giorni?",
    routine_item_days_label: "📅 Giorni",
    home_note_meal_ph: "Cerca un pasto salvato…",
    menu_quick_search: "Ricerca rapida",
    nm_times_hint: "Consiglio: puoi mettere l'ora più tarda in cui di solito fai ogni pasto – per esempio le 9:00 se mangi spesso verso le 8.",
    room_game_marquee: "Lungo la strada – ci si ferma a godersela",
    room_sand_erase_aria: "Strofina per cancellare la scritta",
    faq_a_home_note_line: "Scrivi nella riga al centro della schermata iniziale e tocca ➤ (o Invio): viene salvata in Note. Tocca 📝 all'inizio della riga e diventa 🛒: allora ciò che scrivi va nella Lista della Spesa. Toccalo ancora per 🍎: scrivi qualche lettera, compaiono i tuoi pasti salvati che corrispondono, e un tocco ne registra uno nei pasti di oggi. Con 🎤 puoi semplicemente dirlo.",
    faq_a_night_mode: "Apri il menu ☰ e tocca 🌙 in alto: tutta l'app diventa scura. ☀️ nello stesso punto riporta il giorno. È anche nelle Impostazioni, sotto Modalità Chiara.",
    faq_q_home_note_line: "Come scrivo una nota veloce dalla schermata iniziale?",
    faq_q_night_mode: "Come passo alla modalità notte?",
    menu_day_mode: "Modalità giorno",
    menu_night_mode: "Modalità notte",
    faq_a_secret_room_yoga: "In fondo al sentiero nel bosco c'è un cancello luminoso e, dietro, vicino a una cascata, le creature del bosco – Lumi, Puffi, Nixie e Sparklet – siedono sui loro tappetini in semicerchio, e Flora, la maestra di yoga, siede di fronte a loro sull'unico tappetino sopra la pietra. Tocca Flora: apre gli occhi, tutto si avvicina e la conversazione comincia piano, con il tempo per leggere – Flora chiede come stanno tutti, ogni creatura risponde a nome suo (con un piccolo disegno di chi sta parlando accanto a ogni riga), e poi chiede a te come ti senti con le persone che ti sono vicine. La conversazione prosegue secondo le tue risposte – persone buone, qualcuno con cui è difficile o un po' di solitudine. Ogni strada finisce con una piccola missione (può andare subito in La Mia Giornata; quando la missione è scrivere qualcosa, c'è uno spazio per scriverlo, e viene salvato nel diario magico) e una posizione con tre respiri insieme. ↩ torna indietro di un passo e ✦ inizia una nuova conversazione. La chiave successiva apre la cascata: sedendoti sulla pietra tutto scompare e resta solo il suono dell'acqua. Chinandoti sullo stagno, dall'acqua sale una domanda – cosa farebbe oggi il tuo vero io? – e la risposta diventa un piccolo compito in La Mia Giornata. È un momento gentile, non un sostituto di una conversazione con un professionista.",
    faq_q_secret_room_yoga: "Cosa succede allo yoga nel bosco?",
    room_back_to_forest: "Torna al sentiero",
    room_back_to_yoga: "Torna allo yoga",
    room_item_waterfall: "La cascata",
    room_waterfall_pool_aria: "Tocca l'acqua",
    room_waterfall_rock_aria: "Siediti sulla roccia",
    room_yoga_guide_aria: "Parla con Flora",
    yg_g_alone: "Grazie di averlo condiviso. Capita a tutti, a volte.",
    yg_g_alone_q: "Cosa ti farebbe bene, anche solo un po'?",
    yg_g_critic: "Una critica può pungere a lungo. Parla di un momento, non di tutta la persona.",
    yg_g_end: "Grazie per questo momento nel cerchio. Puoi tornare quando vuoi.",
    yg_g_gate: "Mettere un confine è permesso. Un confine non è un muro: è un cancello.",
    yg_g_good: "Che bello 💛 Chi ti ha fatto del bene questa settimana?",
    yg_g_good_msg: "Alle persone buone vale la pena dirlo. Un piccolo grazie può rendere speciale tutta la loro giornata.",
    yg_g_hard: "Grazie di averlo detto. Cosa ti pesa di più?",
    yg_g_listen: "Quando nessuno ti ascolta, è faticoso. La tua voce conta, anche quando è sottile.",
    yg_g_new: "Le persone nuove iniziano con un piccolo ciao. Un corso, una passeggiata, un gruppo: un passo.",
    yg_g_old: "Chi ti conosce già è un posto caldo. Basta un messaggio breve.",
    yg_g_start: "E ora tocca a te 🌿 Come ti senti ultimamente con le persone che ti sono vicine?",
    yg_g_used: "Quando diamo e non riceviamo niente, qualcosa dentro si stanca. Va bene accorgersene.",
    yg_name_guide: "Flora",
    yg_name_p1: "Lumi",
    yg_name_p2: "Puffi",
