    yg_o_partner: "Il mio partner",
    yg_o_used: "Sento che si approfittano di me",
    yg_p1_alone: "Noi siamo qui 💛",
    yg_p1_good: "Che bello sentirlo! Mi ha scaldato il cuore.",
    yg_p1_start: "La mia settimana è stata piena, ma una cara amica mi ha chiamata proprio al momento giusto.",
    yg_p2_hard: "È successo anche a me. Dirlo ad alta voce mi ha già aiutato.",
    yg_p2_start: "Ascoltare tutti aiuta anche me.",
    yg_pose_child: "Ora la posizione del bambino 🌙 Ginocchia a terra, fronte sul tappetino: un posto sicuro per respirare. Tre respiri insieme.",
    yg_pose_heart: "Ora cuore aperto 💗 Spalle indietro, petto ampio. Tre respiri insieme.",
    yg_pose_tree: "Ora la posizione dell'albero 🌳 In piedi e stabili, un piede sull'altra gamba, mani in alto. Tre respiri insieme.",
    yg_task_good: "Mandare oggi un piccolo messaggio di ringraziamento",
    yg_task_hard: "Scrivere una frase che vorrei dire",
    yg_task_new: "Trovare un posto dove conoscere persone nuove",
    yg_task_old: "Mandare “ti ho pensato” a qualcuno",
    nm_time_hour: "Ora",
    nm_time_minutes: "Minuti",
    routine_time_taken: "A quest'ora c'è già qualcosa: {title}",
    faq_a_new_me_times: "Nel questionario iniziale e, in qualsiasi momento, nelle impostazioni di New Me → “Orari dei pasti”. Se la tua routine ha già orari per i pasti, vengono presi da lì – e i pasti della routine si possono nascondere, mostrando al loro posto i pasti di New Me. Se no, scegli quanti pasti al giorno (2 pasti + uno spuntino / 2 pasti + una cena leggera / 2 pasti + uno spuntino + una cena leggera) e quando ognuno. Con “2 pasti + uno spuntino” sono pranzo alle 11:30, spuntino alle 16:00 e cena alle 19:00 (ognuno si può cambiare). Questi sono gli orari dei tuoi pasti ovunque: nel corridoio, in La Mia Giornata, in La Mia Routine e nei promemoria. Qualunque sia la scelta, le calorie della giornata restano le stesse: quello che si toglie viene diviso tra gli altri pasti.",
    faq_q_new_me_times: "Come imposto gli orari dei pasti in New Me?",
    nm_times_count: "Quanti pasti al giorno?",
    nm_times_from_routine: "Sì, prendili dalla mia routine",
    nm_times_hide: "Nascondi i pasti della mia routine e mostra al loro posto i pasti di New Me",
    nm_times_later: "Più tardi",
    nm_times_manual: "No, scegli qui",
    nm_times_none_found: "La tua routine non ha ancora pasti: scegli qui quanti e quando.",
    nm_times_q: "La tua routine ha orari fissi per mangiare?",
    nm_times_saved: "Orari dei pasti salvati",
    nm_times_title: "Orari dei pasti",
    faq_a_routine_exact_time: "Sì. Quando descrivi una routine all'IA con un orario preciso (come \"16:10 trading\"), viene salvato esattamente così, senza arrotondare all'ora piena. Tutto ciò che è scritto nella routine compare sempre sulla bacheca, anche se quell'ora non è scelta nelle impostazioni delle ore, e togliere un'ora che contiene qualcosa chiede prima conferma. Puoi anche cambiare un orario a mano: tocca l'orario nella finestra dell'elemento e scegli ora e minuti.",
    faq_q_routine_exact_time: "La mia routine può avere un orario preciso, come 16:10?",
    room_item_sand: "Scrivere sulla sabbia",
    room_item_yoga: "Yoga nel bosco",
    room_sand_ph: "Cosa vorresti lasciar andare?",
    room_sand_write: "Scrivi",
    room_song_1: "Per Elisa · Beethoven",
    room_song_2: "Inno alla gioia · Beethoven",
    room_song_3: "Canone in re · Pachelbel",
    room_song_4: "Gymnopédie n. 1 · Satie",
    room_song_5: "Greensleeves · tradizionale",
    room_vinyl_stop: "⏹ Ferma",
    routine_hour_remove_text: "Ciò che è scritto a quest'ora verrà eliminato dalla routine: {title}",
    routine_hour_remove_title: "Togliere {time}?",
    faq_a_routine_ai: "In La Mia Routine apri ⚙️ (o ➕) e tocca \"Una nuova routine con l'IA\": descrivi la routine con parole semplici – per esempio \"sveglia alle 7, palestra alle 8, lavoro fino alle 17\" – e l'IA crea una nuova scheda con gli orari e le attività. Se il testo dice quali giorni (\"nei giorni feriali\"), la scheda si apre in quei giorni, e routine diverse per giorni diversi diventano schede separate. Poi si può modificare tutto come sempre.",
    faq_a_routine_daysoff: "In La Mia Routine tocca ➕ e poi \"Giorni liberi\": scegli i giorni (per esempio sabato e domenica) e la routine di quei giorni – nessun programma (resta libero), la tua routine, oppure racconta all'IA cosa fai perché la costruisca. I giorni liberi hanno una scheda tutta loro, e in quei giorni La Mia Routine e La Mia Giornata mostrano solo quella scheda.",
    faq_q_routine_ai: "Come creo una routine con l'IA?",
    faq_q_routine_daysoff: "Come imposto i giorni liberi in La Mia Routine?",
