    routine_daysoff_which: "Quali giorni?",
    faq_a_secret_room_diary: "Solo tu. Le pagine del diario sono salvate nel tuo account, quindi sono su ogni dispositivo e nessun altro può vederle. Si apre dal diario magico sulla scrivania nella stanza segreta, e anche dal diario nell'angolo della musica. Sotto la pagina nuova c'è una tabella mensile ripiegata: un punto segna ogni giorno che ha una pagina, e toccando un giorno si aprono le sue pagine; lì si può anche eliminare una pagina. Quando il diario è già aperto, si può anche aggiungere al menu principale, con l'interruttore nel diario stesso o nelle impostazioni di New Me.",
    faq_a_secret_room_places: "Ogni ingresso al cancello del bosco si apre con la sua chiave. Dietro: il portico sul mare (sul tavolino la lampada di Aladino – un tocco e ne esce uno spirito del bosco in una nebbia magica, volteggia intorno e comincia una conversazione sul tuo desiderio – vedi “Cosa fa il genio della lampada?”), la chitarra e il diario (la chitarra suona una melodia breve e calma e si ferma da sola, e ognuno dei tre dischi appesi all'albero suona una sua melodia magica – un altro tocco la ferma – e il diario sul ceppo è per scrivere), la stanza del respiro (un lago tranquillo al tramonto: sull'acqua galleggia una lanterna di loto – toccala, scrivi un desiderio e si allontana con lui, lontano, in fondo al lago; con la bacchetta magica puoi scrivere sulla sabbia ciò che vuoi lasciar andare, e resta finché non lo cancelli con il dito) e il sentiero nel bosco (si apre di notte, e toccando le lanterne si passa al giorno; dal grande ramo pende un'altalena magica, la panchina è per sedersi, e toccando il cartello si avvicina: una tavola con sei piccole domande da spuntare). Su un ingresso chiuso si vede quante chiavi mancano. In fondo al sentiero, un cancello luminoso porta allo yoga vicino alla cascata – e da lì alla cascata stessa.",
    faq_q_secret_room_diary: "Chi vede il diario?",
    faq_q_secret_room_places: "Cosa c'è dietro le porte del corridoio?",
