    ai_chat_working_table: "Un attimo, creo la tabella…",
    dev_weather_preview_label: "Anteprima – solo sul tuo account:",
    faq_a_ai_chat: "Tocca la bolla e si apre una chat. Scegli cosa fare – qualcosa per il calendario, cosa hai mangiato, la foto di una ricetta o una nuova tabella – oppure scrivi e basta, e l'assistente capisce da solo. Per il calendario puoi scegliere una volta, ogni settimana o ogni giorno. La risposta arriva nella chat, e da lì puoi passare ad altro o aprire il calendario / cosa hai mangiato.",
    faq_a_new_me_hall: "New Me si apre al cancello di un bosco incantato, e ogni ingresso è un posto: la porta rotonda nell'albero gigante porta nella stanza segreta, il tronco cavo al portico sul mare, la casetta a fungo alla chitarra e al diario, il piccolo arco di salice alla stanza del respiro, il grande arco di salice al sentiero nel bosco, e l'arco di fiori con la scala, una volta aperto il tetto delle stelle, sale lassù. Su un ingresso chiuso c'è un lucchetto. Sul sentiero fluttua il tuo personaggio, Me, e tutto intorno ci sono i pulsanti del gioco: la prossima missione, la sfida della settimana, lo zaino magico con tutto New Me, la mappa del mondo e gli strumenti. Toccando le chiavi in alto si scopre come si guadagnano le chiavi.",
    faq_a_new_me_routine_meals: "Quando in New Me sono impostati i pasti e anche La Mia Routine ha dei pasti, New Me chiede se nasconderli e mostrare al loro posto i pasti di New Me – così niente compare due volte. La Mia Routine mostra allora i pasti di New Me ai loro orari, con 💎 e un ✓; toccando il nome di un pasto si apre una finestra per scegliere un altro pasto o cambiarne l'orario, proprio lì sopra la routine. Non si cancella nulla: tornano da ⚙️ Impostazioni → Pasti nella routine in New Me, oppure spegnendo “Sincronizza con New Me” nell'⚙️ di La Mia Routine. Senza un New Me attivo, tornano da soli.",
    faq_a_room_computer: "È una piccola chat che inizia con “Come sta andando la tua giornata finora?” – bene, piena o difficile – e prosegue con te passo dopo passo, fino a una piccola missione finale (che può anche finire direttamente in La Mia Giornata). Le risposte si possono toccare o scrivere liberamente – ciò che scrivi viene collegato alla risposta più vicina. “↩ Indietro” torna di un passo per rispondere diversamente, e “Nuova chat” ricomincia da capo in qualsiasi momento. Dopo una giornata piena o difficile puoi tornare al computer più tardi lo stesso giorno: “Sono di nuovo qui...” riprende la conversazione. La luce verde in basso spegne e accende il computer. Si salvano solo le scelte, solo su questo dispositivo e solo fino a fine giornata.",
    faq_q_ai_chat: "Come parlo con l'assistente?",
