    dictation_btn_aria: "Parla e viene scritto",
    dictation_mic_denied: "Il microfono è bloccato: consentilo dal 🔒 accanto all'indirizzo nel browser o nelle impostazioni del telefono",
    faq_a_dictation: "Sì: tocca il microfono 🎤 nell'angolo della nota veloce o di una pagina di scrittura del quaderno, e parla: le parole si scrivono mentre parli, nella lingua dell'app. Toccalo di nuovo per fermare. La prima volta il browser chiede il permesso di usare il microfono. Funziona su Chrome / Android e su Safari per iPhone. Sul computer servono un microfono e un browser come Chrome, Edge o Safari: se manca qualcosa, il messaggio dice esattamente cosa.",
    faq_q_dictation: "Posso parlare invece di scrivere?",
    faq_a_secret_room: "Una stanza solo tua, dentro New Me – una casa dentro un albero gigante. Vedi una parete alla volta e ti giri con le frecce (o con uno swipe). La prima chiave arriva dopo un ✓ su un pasto in 3 giorni diversi e apre la porta – e con lei tutta la stanza: il computer, il gioco, il giradischi, la mensola con la biblioteca dentro e il gatto. Poi ogni sfida conclusa (anche la sfida della settimana) dà una chiave che apre il luogo successivo: il tetto delle stelle, il portico sul mare, la chitarra e il diario, la stanza del respiro, il sentiero nel bosco con lo yoga, la cascata e una sorpresa sul tetto – e l'8ª porta una bottiglia dal mare, con dentro la lettera dal passato. Quando qualcosa si apre, una freccia mostra la strada. Si apre anche la porticina in basso nella macchina da gioco – per ora l'armadietto dietro è vuoto. Sul tetto delle stelle, una stella toccata cade come una stella cadente, e il gatto sta seduto sul cuscino.",
