    room_wall_window_hint: "Tocca un oggetto per avvicinarti · le frecce girano la stanza",
    room_wall_window_title: "La finestra e il computer",
    faq_a_steps_in_sport: "In cima a Monitoraggio Allenamenti, in una piccola striscia: i passi di oggi e di questa settimana. I passi verranno contati da soli quando l'app si collegherà a Google Fit / Apple Health nella versione per telefono – il pulsante 🔗 accanto lo spiega.",
    faq_q_steps_in_sport: "Dov'è il contapassi giornaliero?",
    sport_steps_today_label: "passi oggi",
    sport_steps_week_label: "questa settimana",
    faq_a_reminders_one_place: "Ogni promemoria arriva una volta sola, in un solo posto. Se hai l'app aperta davanti (sul computer, sull'iPad o sul telefono), compare lì; altrimenti arriva come notifica solo sul telefono. '✅ Fatto, grazie!' o 'Capito!' in qualsiasi posto lo chiude su tutti i dispositivi, e non torna più. 'Non ancora' lo rimanda: torna ogni 5 minuti, ogni volta in un solo posto. Spuntare l'attività con ✓ nell'elenco conta anche come fatto. Per ricevere le notifiche anche su computer e tablet, attiva 'Anche su computer e tablet' in Impostazioni > Notifiche.",
    faq_q_reminders_one_place: "Perché un promemoria arriva una volta sola, e solo sul telefono?",
    reminder_all_devices_hint: "Di norma ogni promemoria arriva una volta sola, in un solo posto: sul telefono, o sul dispositivo dove hai l'app aperta davanti. Fatto o Capito in un posto lo chiude ovunque.",
    reminder_all_devices_label: "Anche su computer e tablet",
    myday_water_info: "8 bicchieri d'acqua medi / piccoli sono in media circa 2 litri",
    faq_a_good_things: "La sera (dalle 18:00) sotto la data appare un piccolo pulsante: scrivi fino a 3 cose belle successe oggi – ne basta anche una. Vengono salvate, e in 'Giorni precedenti' vedi quello che hai scritto prima. 'Non stasera' lo nasconde fino a domani, e puoi disattivarlo del tutto in Impostazioni > Personalizzazione e calendario.",
    faq_a_home_countdown: "Segna un evento con ⭐ nel calendario (la stella accanto a esso nell'elenco degli eventi). L'evento segnato più vicino nei prossimi 100 giorni appare sotto la data – 'Mancano 3 giorni · Compleanno della mamma', 'Domani · …' o 'Oggi · …'. Toccalo per andare a quel giorno nel calendario.",
    faq_a_home_streak: "Conta quanti giorni di fila hai avuto almeno una ✓ – qualsiasi cosa nella Mia Giornata, nella Mia Routine, nei Miei Obiettivi o in New Me. Appare da 2 giorni in su. Se oggi non c'è ancora una ✓, la serie non è interrotta – c'è ancora tutto il giorno. E se finisce, sparisce semplicemente in silenzio, senza sensi di colpa.",
    faq_a_home_weather: "Attiva 'Il meteo nel cielo della schermata iniziale' in Impostazioni > Personalizzazione e calendario e consenti la posizione. Il cielo della schermata iniziale mostra allora il meteo reale dove ti trovi – sole (o luna e stelle di notte), nuvole, pioggia, neve, temporale o nebbia – in tutti i temi, aggiornato circa ogni 40 minuti. La tua posizione approssimativa (arrotondata a circa 1 km) resta solo sul tuo dispositivo e viene controllata tramite il nostro server presso MET Norway. È disattivato per impostazione predefinita. Sotto l'interruttore c'è scritto che tempo fa fuori adesso – per esempio ⛅ Parzialmente nuvoloso, ecco perché in cielo ci sono sia il sole sia le nuvole.",
    faq_q_good_things: "Cos'è \"3 cose belle di oggi\"?",
    faq_q_home_countdown: "Come ottengo un conto alla rovescia nella schermata iniziale?",
    faq_q_home_streak: "Cos'è il 🔥 \"giorni di fila\" sotto il saluto?",
    faq_q_home_weather: "Come ottengo il meteo nel cielo della schermata iniziale?",
    good_things_chip: "3 cose belle di oggi",
    good_things_chip_done: "3 cose belle ✓",
    good_things_hint: "Qualcosa di piccolo che oggi è andato bene – ne basta anche una.",
