    settings_good_things_label: "\"3 cose belle\" la sera",
    settings_weather_hint: "Pioggia, nuvole o neve sullo sfondo della schermata iniziale, in base al meteo dove ti trovi. La tua posizione approssimativa resta su questo dispositivo e viene controllata tramite il nostro server presso MET Norway.",
    settings_weather_label: "Il meteo nel cielo della schermata iniziale",
    weather_failed: "Non è stato possibile controllare il meteo in questo momento.",
    weather_location_denied: "Nessun accesso alla posizione – consentilo nelle impostazioni del browser e riprova.",
    faq_a_home_focus: "Tocca ◎ in alto nella schermata Home: sparisce tutto tranne l'unica cosa di adesso – quella di quest'ora, o la prossima della lista di oggi – con una grande ✓ e Nota Rapida. Dopo la ✓ compare la cosa successiva. Tocca 'Modalità focus ✕' in alto per riavere tutto.",
    faq_a_home_search: "Apri il menu ☰: la ricerca è proprio in alto. Scrivi almeno 2 lettere: i risultati arrivano da note, lista della spesa, calendario, ricette, quaderni (titoli e testo delle pagine), obiettivi, tabelle e libri, raggruppati per tipo – toccane uno per andarci subito.",
    faq_a_my_day: "La Mia Giornata riunisce quelli che erano Uno Sguardo a Oggi e La Mia Routine su un'unica linea del tempo. In basso nella schermata Home vedi quanto è fatto, cosa c'è adesso o dopo (con una ✓ veloce) e, accanto al titolo, un bicchiere d'acqua con +1. Toccala (o scorrila verso l'alto) per aprire tutta la giornata: in alto ciò che non ha orario, poi tutto per ora – attività, eventi e riunioni del calendario, gli orari fissi della settimana, la routine di oggi, i piccoli passi dei tuoi obiettivi e i pasti di New Me – con una linea per adesso. Filtra per Attività, Routine o Riunioni ed eventi. Una ✓ qui è la stessa ✓ ovunque (La Mia Routine, I Miei Obiettivi, il calendario) e fa sbocciare una margherita nell'angolo. 'Modifica la routine' apre La Mia Routine (anche nel menu) e '＋ Aggiungi per oggi' aggiunge un'attività per oggi. Toccando il titolo \"La Mia Giornata\" (o la barretta in alto) si richiude.",
