    bag_ex_txt_moments: "Piccole cose che ci hanno resi felici questa settimana:\n• Una passeggiata serale insieme dopo cena\n• Un disegno ricevuto in regalo\n• Tante risate a cena",
    bag_ex_txt_recipes: "2 tazze di farina\n2 uova\n1 tazza e mezza di latte\n1 cucchiaio di zucchero\n\nMescola tutto, scalda una padella e cuoci dei piccoli pancake finché sono dorati.",
