    faq_a_new_me_tour: "Subito dopo l'acquisto e il breve questionario, un breve tour mostra il gioco: la barra in alto, la prossima missione, gli strumenti ai due lati, la sfida della settimana, lo zaino magico, la mappa del mondo, il tuo personaggio Me e la porta 1 verso la stanza segreta. Si può rivedere in qualsiasi momento da ⚙️ Impostazioni > 🧭 Tour di New Me – lì si può anche cambiare il nome completo del questionario. Prima dell'acquisto, accanto a New Me nel menu compare un 🔒, e toccandolo si apre una pagina con tutto ciò che è incluso.",
