    faq_a_new_me_advanced: "La Modalità avanzata si apre con il regalo, dopo tutte le 20 sfide, e si può attivare o disattivare in 🎁 Il tuo regalo. Dà a New Me un look dorato, menu libero – ogni cambio mostra tutte le opzioni senza limite di calorie – e una schermata 📊 Statistiche avanzate: le calorie degli ultimi 30 giorni rispetto al piano, i giorni buoni per giorno della settimana, l'andamento del peso con una stima di quando si raggiunge l'obiettivo, le medie del check-in serale e lo storico delle sfide.",
