    nm_gift_locked_view: "Il regalo si apre dopo tutte le {n} sfide – ne mancano {left}.",
    nm_gift_intro: "Tutte le {n} sfide, un passo alla volta. Ecco cosa ti aspettava:",
    nm_gift_title: "Il tuo regalo",
    faq_a_new_me_letter_gift: "All'inizio di New Me (o più tardi, in Sfide) si può scrivere una lettera al tuo io del futuro. Una volta sigillata, non si può leggere né modificare finché non si apre: nella bottiglia dal mare, nella stanza segreta, oppure alla fine di tutte le 20 sfide – dove ti aspetta anche un regalo.",
    faq_q_new_me_letter_gift: "Cos'è la lettera dal passato?",
    faq_a_new_me_challenges: "🏆 Sfide contiene 20 sfide: 10 grandi (come 5 giorni senza zucchero, una settimana senza carboidrati o perdere 4 kg in un mese – deficit calorico, allenamento e niente zucchero ogni giorno) e 10 mini – piccole abitudini per una settimana, come il caffè alla cannella senza zucchero. Scegliendo una sfida viene chiesto quando iniziare: oggi, domani, la settimana prossima o un'altra data. Una grande sfida e una mini sfida possono andare insieme. La sfida in corso compare in cima al menu e nella Mia Giornata, con una ✓ per il giorno. Ogni settimana di sfida porta un giorno libero (🍕) che non la interrompe, e un giorno non segnato conta come giorno libero – si può segnare oggi e anche ieri. Alcuni giorni si segnano da soli: un allenamento di 20 minuti in Monitoraggio Allenamenti, o i pasti del menu con ✓. Ogni sfida ha una ⓘ con cosa conta esattamente (per esempio la lista completa dei carboidrati) – nella sfida stessa e accanto, nella Mia Giornata. Sotto, 🌱 Crescita personale ha 48 piccole sfide di una settimana (non contano nelle 20) – vedi “Cos'è la sfida della settimana?”.",
    faq_q_new_me_challenges: "Come funzionano le sfide di New Me?",
    nm_letter_too_short: "Ancora qualche parola 🙂",
    nm_letter_quiz_note: "Facoltativa – si può scrivere anche più tardi, in Sfide.",
    nm_letter_write: "✍️ Scrivi la lettera",
    nm_letter_sealed_line: "Sigillata il {date} · si apre dopo le {n} sfide",
    nm_letter_sealed_toast: "Sigillata ✉️ – ci vediamo al traguardo",
    nm_letter_seal_note: "Una volta sigillata, la lettera non si può leggere né modificare finché tutte le sfide non sono completate.",
    nm_letter_seal: "✉️ Sigilla la lettera",
    nm_letter_ph: "Dove sono oggi, dove voglio arrivare, cosa mi riesce difficile con il cibo, cosa vorrei dirmi al traguardo…",
    nm_letter_intro: "Si scrive adesso e si sigilla – si apre solo dopo tutte le {n} sfide, per vedere quanto è cambiato da allora. Dove sono adesso? Quali sono i miei obiettivi e cosa mi riesce difficile con il cibo?",
