    nm_ch_start_title: "Quando iniziare?",
    nm_ch_rule: "Un giorno libero per ogni settimana di sfida. Un giorno non segnato conta come giorno libero – si può segnare oggi e anche ieri. Una grande sfida e una mini sfida possono andare insieme.",
