    nm_ch_completed_label: "sfide completate",
    nm_tile_challenges: "Sfide",
    faq_a_workout_calories: "Sì. Ogni allenamento riceve una stima delle calorie bruciate – in base a tipo, durata e al tuo ultimo peso (per corsa e bici anche in base alla velocità, se è inserita una distanza). Compare nella lista degli allenamenti e nel riepilogo mensile (Bruciate) e si aggiunge al budget di calorie di quel giorno: nel Diario Alimentare Giornaliero, nelle Metriche di Calorie e Peso e nell'anello di New Me. È una stima, per questo ha il ~.",
    faq_q_workout_calories: "Gli allenamenti contano nelle mie calorie del giorno?",
    faq_a_new_me_flexible_menu: "Sì. Nel questionario e nelle impostazioni si sceglie quanti pasti al giorno – 2 pasti + uno spuntino / 2 pasti + una cena leggera / 2 pasti + uno spuntino + una cena leggera – e ➖ sulla scheda di un pasto lo toglie (ne restano almeno 3); “Rimetti” lo riporta. In ogni caso le calorie della giornata restano le stesse: quello che si toglie viene diviso tra gli altri pasti, e sotto ogni pasto è scritto quanto è stato aggiunto e cosa ci si può abbinare. ✏️ Modifica su un pasto apre il suo testo – cambia ciò che vuoi (es. senza pane o con un uovo in più) e l'IA ricalcola calorie e proteine. 🔄 Cambia offre opzioni dal menu, ⭐ Salvati e ✨ Scrivilo; ogni modifica può valere solo per oggi o da ora in poi. E alla fine di “Tutta la giornata” c'è ➕ Aggiungi cibo – scrivi cosa è stato mangiato fuori dal menu, l'IA lo calcola e lo aggiunge a oggi (✕ lo elimina).",
    faq_q_new_me_flexible_menu: "Posso cambiare il numero di pasti in New Me, o mangiare un pasto mio?",
    daily_calorie_mini_burn: "+🔥 {amount} dagli allenamenti",
