    sport_total_kcal: "Bruciate",
    nm_swap_ai_too_big: "Un po' più di quanto resta per oggi – ci stanno fino a ~{n} kcal. Puoi registrarlo comunque – gli altri pasti di oggi diventano più piccoli per bilanciare – oppure scegliere una porzione più piccola.",
