    vision_tagline: "Grandi obiettivi, piccoli passi.",
    faq_a_app_tour: "Il tour si apre da solo una volta, al primo accesso. Comincia dalle sue parti – tocca una parte per andarci subito – poi mostra tutte le parti dell'app (la schermata iniziale, l'assistente IA e ogni voce del menu) e i cinque gruppi delle Impostazioni, ciascuno con una breve spiegazione, e dà un'occhiata all'interno di alcuni (per esempio un percorso obiettivo di esempio, lo zaino e Google Calendar). Continua va avanti, Indietro torna indietro, Salta questa parte passa alla parte successiva e ✕ chiude il tour. Puoi rivederlo quando vuoi da Impostazioni > Aiuto e utilizzo > Tour dell'app, e riprendere da dove avevi lasciato. Continua e Indietro restano sempre nello stesso punto, in fondo allo schermo, e sul computer funzionano anche le frecce della tastiera.",
    faq_q_app_tour: "Come posso rivedere il tour dell'app?",
