    apptour_s_notifications_text: "Le notifiche dei promemoria e il loro suono. '⏰ Non ancora' su un promemoria funziona come lo snooze della sveglia: te lo ricorda di nuovo ogni 5 minuti.",
    apptour_s_personalization_text: "Paese, pasti e spuntini al giorno, quando inizia il tuo mese finanziario e cosa compare nella schermata iniziale.",
    apptour_s_appearance_text: "Lingua, modalità chiara o scura, temi, font, colore del testo, accessibilità e dimensione dell'app.",
    apptour_m_style_text: "Questo pulsante passa il menu ai grandi riquadri – e viceversa. Nella schermata iniziale ne compare solo uno.",
