    nm_drink_more: "+ Altra bevanda",
    nm_drink_add: "Aggiungi",
    nm_drink_name_ph: "Bevanda (es. succo)",
    nm_drinks_hint: "Basta scrivere la bevanda – le calorie vengono calcolate automaticamente e il numero si può modificare.",
    nm_slot_drinks: "Bevande",
    faq_a_new_me_tracking: "Tocca la prossima missione in alto in New Me e poi ✓ Mangiato per segnare come mangiato il prossimo pasto – il menu completo con la ✓ su ogni pasto è in Tutta la giornata, di lato, e i pasti di oggi compaiono anche in La Mia Giornata nella schermata Home – toccandone uno lì (o passandoci sopra con il mouse) si vede esattamente cosa mangiare, con ✓ e Cambia. Tutto è sincronizzato con il Diario Alimentare Giornaliero: i pasti del piano, le bevande e tutto ciò che aggiungi altrove (per esempio un caffè dall'aggiunta rapida) vengono contati insieme in New Me e in La Mia Giornata – niente di ciò che hai già scritto viene sovrascritto, e togliere una ✓ toglie solo la parte di New Me. Quando tutti i pasti di oggi sono segnati c'è una piccola festa. In “Bevande” si registrano le bevande del giorno – in tutto fino a ~150 kcal, cioè circa 3 bevande da ~50 kcal ciascuna al massimo. Basta scrivere il nome della bevanda e le calorie vengono compilate automaticamente dall'IA. Le due righe caffè/tè hanno anche un campo “Latte? Quanto?” (per esempio “un po'” o “50 ml”), e il calcolo si aggiorna; il numero si può cambiare prima di aggiungere e anche dopo. Una bevanda con nome e calorie viene salvata automaticamente appena passi oltre – toccare Aggiungi è facoltativo. Tocca ☆ accanto a una bevanda per salvarla come abituale – le bevande abituali compaiono come pulsanti in cima alla scheda Bevande, e un tocco le aggiunge alla giornata. ⭐ salva un pasto come pasto salvato. “Tabella giornaliera” mostra cosa hai mangiato con calorie e proteine. Il piccolo 💎 accanto alla modalità focus, in alto nella schermata Home, lo apre direttamente. I valori di calorie e proteine sono stime dell'IA e possono contenere errori. Non hai mangiato tutto? Sotto un pasto segnato, “Non hai mangiato tutto?” toglie un quarto, metà o tre quarti della porzione – o quello che scrivi, calcolato – e le calorie del giorno si aggiornano.",
    faq_q_new_me_tracking: "Come funzionano ✓, cambi e calorie in New Me?",
    faq_a_new_me_what: "New Me è un programma di menu giornaliero a parte, con due piani pronti – 1.300 o 1.500 calorie – composti da 2 pasti principali e 2 spuntini, con 3 opzioni per ciascuno. Include tutto Premium. Prezzo: $11,99 al mese (disdici quando vuoi) oppure $99,99 una volta sola, a vita. Si apre da 💎 New Me nel menu. Prima di iniziare c'è un breve questionario che comincia con un'avvertenza medica da accettare. Il programma è solo un'informazione generale e non sostituisce un medico o un dietista clinico.",
    faq_q_new_me_what: "Che cos'è New Me e come si ottiene?",
