    onboarding_skip_link: "Salta", onboarding_next_btn: "Avanti", onboarding_welcome_title: "Benvenuto su NOT10.ai!", onboarding_welcome_subtitle: "Un'unica app per attività, alimentazione, finanze e abitudini - configuriamo tutto in meno di un minuto.", onboarding_welcome_btn: "Iniziamo", onboarding_country_title: "Dove ti trovi?", onboarding_phone_title: "Numero di telefono (facoltativo)", onboarding_phone_subtitle: "Solo per aggiornamenti futuri - del tutto facoltativo, salta pure se preferisci.", onboarding_phone_placeholder: "Numero di telefono", onboarding_goal_title: "Qual è un obiettivo che hai in mente adesso?", onboarding_goal_placeholder: "es. Risparmiare per un viaggio, correre 5 km...", onboarding_goal_hint: "Lo aggiungeremo a 'I Miei Obiettivi' - puoi saltare anche questo.", onboarding_tour_offer_title: "Vuoi un tour di 1 minuto?", onboarding_tour_offer_subtitle: "Ti mostriamo le funzioni principali - potrai sempre trovarlo di nuovo nelle Impostazioni.", onboarding_tour_offer_yes: "Sì, mostramelo!", onboarding_tour_offer_no: "No grazie, esploro da solo", settings_replay_tour_btn: "🧭 Tour dell'app", tour_notes_title: "Note e liste", tour_notes_subtitle: "Scrivi un appunto e trascinalo su Oggi, Domani o Più avanti.", tour_calendar_title: "Agenda e calendario", tour_calendar_subtitle: "Tutti i tuoi eventi e attività, settimanali e mensili, in un unico posto.", tour_nutrition_title: "Nutrizione intelligente", tour_nutrition_subtitle: "Descrivi cosa hai mangiato o scatta una foto al tuo piatto - l'IA stima le calorie.", tour_finance_title: "Finanze", tour_finance_subtitle: "Entrate, uscite, spese ricorrenti e un budget mensile che si rinnova da solo.", tour_sport_title: "Sport e abitudini", tour_sport_subtitle: "Tieni traccia di allenamenti, acqua e abitudini quotidiane, tutto in un colpo d'occhio.", tour_vision_title: "Vision Board", tour_vision_subtitle: "Fissa obiettivi, monitora i progressi e festeggia ogni traguardo raggiunto.", tour_done_title: "Tutto pronto!", tour_done_subtitle: "È ora di rendere questa settimana tua.", tour_done_btn: "Iniziamo",
