    food_ai_estimating: "Stima in corso...", food_clarify_title: "Un'altra piccola domanda", food_clarify_placeholder: "Scrivi la tua risposta...", food_ai_unknown_toast: "Non sono riuscito a identificarlo con sicurezza - è stata registrata una stima approssimativa al suo posto. Prova a descriverlo in modo diverso per un risultato più preciso.",
    food_estimate_confirm_summary: "Stimato: {calories} kcal · {protein}g di proteine", food_estimate_confirm_btn: "✓ Va bene, continua", food_estimate_reject_btn: "✗ Non è corretto", food_estimate_reject_question: "Cosa non va? Descrivilo di nuovo, oppure aggiungi i dettagli mancanti.",
    preset_protein_placeholder: "Proteine (g)", stat_today_protein: "Proteine", stat_weekly_protein: "Proteine", stat_monthly_protein: "Proteine", protein_stat_avg_label: "media {amount}g", calorie_monthly_day_total_protein_label: "Proteine:", food_picker_protein_label: "Proteine:",
    daily_calorie_mini_summary: "Oggi: {total} / {goal} cal", daily_calorie_mini_remaining: "{amount} rimaste", daily_calorie_mini_over: "{amount} in più",
    home_calorie_badge_title: "Calorie di oggi", home_greeting_date_peek_title: "Uno sguardo veloce al calendario", home_calorie_badge_label: "Mostra le calorie di oggi in 'La Mia Giornata'", settings_daily_board_tab_label: "Mostra una scheda \"La Mia Routine\"", settings_today_peek_tab_label: "Mostra una scheda \"La Mia Giornata\"",
    calorie_stat_avg_label: "Media: {amount}",
    daily_focus_modal_title: "🧠 Qual è la cosa più importante da fare oggi?", daily_focus_modal_subtitle: "Rispondi, e verrà aggiunta subito al programma di oggi.", daily_focus_input_placeholder: "Oggi voglio soprattutto", daily_focus_save_btn: "Aggiungi al programma di oggi", daily_focus_skip_btn: "Non ora", daily_focus_missing_text: "Scrivi prima qualcosa", daily_focus_added_toast: "Aggiunto al programma di oggi", daily_focus_other_option: "✍️ Altro...",
    daily_focus_c1_d0: "Proteggere il mio spazio di calma dal rumore intorno a me", daily_focus_c1_d1: "Porre confini chiari, con amore e senza sensi di colpa", daily_focus_c1_d2: "Mantenere il mio equilibrio anche quando intorno a me c'è tempesta", daily_focus_c1_d3: "Mettere la mia calma e la mia energia al primo posto", daily_focus_c1_d4: "Non farmi carico delle emozioni e degli stati d'animo altrui", daily_focus_c1_d5: "Non lasciare che le parole degli altri scuotano il mio valore",
    daily_focus_c2_d0: "Ascoltare ciò di cui il mio corpo e la mia mente hanno bisogno", daily_focus_c2_d1: "Godermi le piccole cose lungo il percorso", daily_focus_c2_d2: "Rallentare e connettermi davvero con il mio io interiore", daily_focus_c2_d3: "Darmi spazio per respirare in mezzo alle cose da fare", daily_focus_c2_d4: "Sentirmi a casa e in pace dentro di me", daily_focus_c2_d5: "Concentrarmi su ciò che accade ora, senza correre avanti",
    daily_focus_c3_d0: "Mantenere parole incoraggianti, pazienti e comprensive", daily_focus_c3_d1: "Non prendere nulla sul personale", daily_focus_c3_d2: "Non dare nulla per scontato - solo chiedere, o lasciar perdere", daily_focus_c3_d3: "Fidarmi del mio ritmo e del mio percorso", daily_focus_c3_d4: "Lasciar andare la perfezione e scegliere il progresso", daily_focus_c3_d5: "Avere pazienza con il mio processo",
    daily_focus_c4_d0: "Finire la giornata con un senso di orgoglio e soddisfazione", daily_focus_c4_d1: "Notare i miei progressi, anche nei piccoli passi", daily_focus_c4_d2: "Concentrarmi su un compito alla volta", daily_focus_c4_d3: "Mettere ordine nelle mie cose e agire con calma", daily_focus_c4_d4: "Accettarmi esattamente come sono oggi", daily_focus_c4_d5: "Sapere quando agire e quando lasciar andare",
    daily_focus_c5_d0: "Portare un sorriso e leggerezza in tutto ciò che faccio", daily_focus_c5_d1: "Iniziare la giornata con energia fresca e positiva", daily_focus_c5_d2: "Regalarmi una giornata tranquilla, senza aspettative eccessive", daily_focus_c5_d3: "Portare gioia semplice nella mia routine", daily_focus_c5_d4: "Aprire il mio cuore a belle sorprese oggi", daily_focus_c5_d5: "Iniziare la giornata con gratitudine e un sorriso",
    daily_focus_c6_d0: "Ascoltare davvero, non solo aspettare il mio turno per parlare", daily_focus_c6_d1: "Ricordare che ognuno porta con sé qualcosa di invisibile", daily_focus_c6_d2: "Diffondere intorno a me un'energia calda e accogliente", daily_focus_c6_d3: "Mantenere apertura e rispetto nel mio modo di comunicare", daily_focus_c6_d4: "Vedere il buono nelle persone intorno a me", daily_focus_c6_d5: "Offrire una parola gentile a chi ne ha bisogno oggi",
    daily_focus_c7_d0: "Ricordare ciò che ho, non solo ciò che manca", daily_focus_c7_d1: "Lasciar andare ciò che è fuori dal mio controllo", daily_focus_c7_d2: "Valorizzare la lezione anche quando le cose non vanno come previsto", daily_focus_c7_d3: "Fermarmi un momento e dire grazie per ciò che ho", daily_focus_c7_d4: "Avere fiducia in me e nella mia capacità di affrontare le cose", daily_focus_c7_d5: "Ritrovare un sano senso della misura",
    daily_focus_p1_d1_s1: "Proteggere il mio spazio di calma dal caos intorno a me", daily_focus_p1_d1_s2: "Ascoltare ciò di cui il mio corpo e la mia mente hanno bisogno oggi", daily_focus_p1_d1_s3: "Mantenere un modo di parlare incoraggiante, paziente e comprensivo", daily_focus_p1_d1_s4: "Avanzare con piccoli passi che creano un progresso chiaro", daily_focus_p1_d1_s5: "Portare un sorriso e leggerezza in tutto ciò che faccio",
    daily_focus_p1_d2_s1: "Porre confini chiari a partire dall'amore e dalla fiducia in me", daily_focus_p1_d2_s2: "Lasciar andare con amore ciò che è fuori dal mio controllo", daily_focus_p1_d2_s3: "Scegliere un'interpretazione positiva e costruttiva per ogni situazione", daily_focus_p1_d2_s4: "Vedere e apprezzare i miei progressi durante la giornata", daily_focus_p1_d2_s5: "Iniziare la giornata con un'energia buona e rinnovata",
