    faq_q_daily_focus_prompt: "Cos'è il piccolo promemoria che mi chiede qual è la cosa più importante da fare oggi?", faq_a_daily_focus_prompt: "È un promemoria giornaliero Premium: una volta al giorno compare un piccolo badge “1” sull'icona dell'assistente IA. Tocca il badge per aprire una nuvoletta che ti chiede cosa conta di più per te oggi, con 5 suggerimenti pronti già lì (cambiano ogni giorno, ruotando tra temi diversi per un anno intero così restano sempre nuovi) più 'Altro' per scrivere il tuo - puoi sceglierne più di uno. Tocca Aggiungi e le tue scelte appaiono come piccole etichette promemoria in cima a 'La Mia Giornata' (non sono attività da spuntare). Se la chiudi con ✕ o tocchi fuori, il badge si attenua per il resto della giornata invece di sparire. È attivo di default, ma puoi disattivarlo in Impostazioni > Personalizzazione e calendario. Oggi non è giornata? Tocca '🌙 Oggi no': il badge sparisce fino a domani, quando la domanda torna come sempre. Uno dei suggerimenti arriva dalla tua vita – il prossimo passo dell'obiettivo del mese o la lettura di oggi. Ogni giorno si riparte da zero.",
