    habits_title: "Abitudini", habits_empty_hint: "Ancora nessuna abitudine - aggiungine una per iniziare a tenere traccia della tua serie.", habits_add_modal_title: "Nuova abitudine", habits_name_placeholder: "es. Bere acqua, Leggere, Meditare...", habits_missing_name: "Dai un nome all'abitudine", habits_delete_title: "Eliminare questa abitudine?", habits_delete_confirm: "Questo eliminerà anche permanentemente tutta la sua cronologia e la sua serie.", habits_link_sport_label: "Registra anche come sessione sportiva al completamento", habits_sport_duration_placeholder: "Durata in minuti", habits_missing_sport_duration: "Inserisci la durata in minuti", habit_auto_logged_sport_badge: "Da un'abitudine", habits_overview_btn_title: "Panoramica mensile", habits_overview_title: "Abitudini - Panoramica Mensile", routine_goals_section_title: "🎯 Obiettivi e Abitudini", routine_goals_empty_hint: "Ancora niente in questa scheda - aggiungi elementi alla tua routine per monitorarli qui.", routine_goals_toggle_label: "Mostra il monitoraggio di obiettivi e abitudini",
